import java.util.*;
import java.io.*;
import java.math.*;

/**
 * Auto-generated code below aims at helping you parse
 * the standard input according to the problem statement.
 **/
class Solution {
    static Bricks B = new Bricks();
    static String wall = "";
    static int H, W;

    public static void main(String args[]) {
        Scanner in = new Scanner(System.in);
        int N = in.nextInt();
        System.err.println("N="+N);
        for (int i = 0; i < N; i++) {
            String brickName = in.next();
            int brickSize = in.nextInt();
            String color = in.next();
            int count = in.nextInt();
            B.add(new Brick(brickName, brickSize, color, count));
            System.err.println("brickName="+brickName+" brickSize="+brickSize+" color="+color+" count="+count);
        }
        H = in.nextInt();
        W = in.nextInt();
        System.err.println("H="+H+", W="+W);
        if (in.hasNextLine()) {
            in.nextLine();
        }
        for (int i = 0; i < H; i++) {
            String line = in.nextLine();
            wall=line+wall;
            System.err.println(line);
        }

        Sol sol = new Sol();
        findSol(0, sol);

        for (Place p:sol.list)
            System.out.println(p.brick.brickName + " " + p.pos%W);
    }

    static boolean findSol(int pos, Sol sol) {
        //System.err.println("findSol " + pos + sol);
        if (pos>=H*W) return checkStable(sol);
        char color = wall.charAt(pos);
        if (color == ' ') return findSol(pos+1, sol);
        for (Brick b : B.list) {
            if (b.count==0 || b.color!=color) continue;
            boolean checkB=true;
            for (int i=0; i<b.brickSize;i++)
                if ((i>0&&(pos+i)%W==0) || wall.charAt(pos+i) != color) { checkB=false; break;}
            if (checkB) {
                sol.add(new Place(b, pos));
                b.count--;
                boolean res = findSol(pos+b.brickSize, sol);
                if (res) return true;
                sol.list.removeLast();
                b.count++;
            }
        }
        return false;
    }

    static boolean checkStable(Sol sol) {
        List<Sol> l = new ArrayList<>();
        for (Place p : sol.list) {
            //System.err.println(l);
            if (p.pos/W ==0) { Sol s = new Sol(); s.add(p); l.add(s); continue; }
            boolean hasSupport=false;
            for (int i=0; i<p.brick.brickSize; i++) {
                int subPos = p.pos+i-W;
                if (wall.charAt(subPos) == ' ') continue;
                hasSupport = true;
                Sol firstSol = null;
                for (Sol existingSol : l) {
                    if (existingSol.hasPlace(p)) {
                        firstSol = existingSol;
                    }
                    else if (existingSol.hasPos(subPos)) {
                        if (firstSol == null) {
                            existingSol.add(p); 
                            firstSol = existingSol; 
                        }
                        else {
                            for (Place p2 : existingSol.list)
                                firstSol.add(p2);
                            existingSol.list.clear();
                        }
                    }
                }
            }
            if (!hasSupport) return false;

        }
        int size = 0;
        for (Sol s : l)
            if (s.size() > 0) size++;
        return size==1;
    }
}

class Brick {
    String brickName;
    char color;
    int brickSize, count;

    Brick(String n, int s, String c, int i) { brickName = n; brickSize = s; color = c.charAt(0); count = i; }
}

class Bricks {
    List<Brick> list = new ArrayList<>();

    void add(Brick b) { list.add(b); }
    int size()  {return list.size();}
    Brick get(int i) { return list.get(i); }
}

class Place {
    Brick brick;
    int pos;
    Place(Brick b, int p) { brick=b; pos=p; }

    public String toString() {
        return brick.brickName + "-"+pos;
    }

}

class Sol {
    List<Place> list = new ArrayList<>();

    void add(Place p) { list.add(p); }
    int size()  {return list.size();}
    Place get(int i) { return list.get(i); }

    boolean hasPlace(Place p) {
        return list.contains(p);
    }

    boolean hasPos(int pos) {
        for (Place p : list)
            if (pos >= p.pos && pos<p.pos+p.brick.brickSize) return true;
        return false;
    }

    public String toString() {
        return list.toString();
    }
}
